import { useQuery } from '@tanstack/react-query';
import { transferApi } from '../../api/services';
import { Table, Badge } from '../../components/ui';
import { format } from 'date-fns';

const statusColor = { PENDING: 'yellow', APPROVED: 'green', REJECTED: 'red' };

export default function TransfersPage() {
  const { data, isLoading } = useQuery({
    queryKey: ['transfers'],
    queryFn: () => transferApi.getAll({ page: 0, size: 20 }),
  });

  const transfers = data?.data?.data?.content || data?.data?.data || [];

  const columns = [
    { key: 'employeeCode', label: 'Employee' },
    { key: 'fromDepartment', label: 'From Dept' },
    { key: 'toDepartment', label: 'To Dept' },
    { key: 'fromBranch', label: 'From Branch' },
    { key: 'toBranch', label: 'To Branch' },
    { key: 'effectiveDate', label: 'Effective Date', render: (r) => r.effectiveDate ? format(new Date(r.effectiveDate), 'dd MMM yyyy') : '—' },
    { key: 'status', label: 'Status', render: (r) => <Badge label={r.status} color={statusColor[r.status] || 'gray'} /> },
  ];

  return <Table columns={columns} data={transfers} loading={isLoading} />;
}
